def forwards_validation_workflow_version_node_templates(apps, schema_editor):
    ValidationWorkflow = apps.get_model("iaso", "ValidationWorkflow")
    ValidationWorkflowVersion = apps.get_model("iaso", "ValidationWorkflowVersion")
    ValidationNodeTemplate = apps.get_model("iaso", "ValidationNodeTemplate")

    BATCH_SIZE = 500

    versions_to_create = []

    for wf in ValidationWorkflow.objects.iterator(chunk_size=BATCH_SIZE):
        versions_to_create.append(
            ValidationWorkflowVersion(
                main_workflow=wf,
                version="1.0.0",
                version_major=1,
                version_minor=0,
                version_patch=0,
                created_by=wf.created_by,
                updated_by=wf.updated_by,
            )
        )

        if len(versions_to_create) >= BATCH_SIZE:
            ValidationWorkflowVersion.objects.bulk_create(
                versions_to_create,
                batch_size=BATCH_SIZE,
            )
            versions_to_create.clear()

    if versions_to_create:
        ValidationWorkflowVersion.objects.bulk_create(
            versions_to_create,
            batch_size=BATCH_SIZE,
        )
        versions_to_create.clear()

    latest_versions = ValidationWorkflowVersion.objects.order_by(
        "main_workflow",
        "-version_major",
        "-version_minor",
        "-version_patch",
    ).values("id", "main_workflow_id")

    latest_version_map = {}
    for v in latest_versions.iterator(chunk_size=BATCH_SIZE):
        if v["main_workflow_id"] not in latest_version_map:
            latest_version_map[v["main_workflow_id"]] = v["id"]

    for workflow_id, version_id in latest_version_map.items():
        ValidationNodeTemplate.objects.filter(workflow_id=workflow_id).update(new_workflow_id=version_id)


def reverse_validation_workflow_version_node_templates(apps, schema_editor):
    """
    This one is tricky:

    If a validation workflow has multiple versions, we must create other validation workflows for each versions , so we don't loose the history of instance (even though the API might not display the results correctly anymore, at least it won't be erased from db).

    """

    ValidationWorkflow = apps.get_model("iaso", "ValidationWorkflow")
    ValidationWorkflowVersion = apps.get_model("iaso", "ValidationWorkflowVersion")
    ValidationNodeTemplate = apps.get_model("iaso", "ValidationNodeTemplate")

    workflows = (
        ValidationWorkflow.objects.filter(versions__isnull=False)
        .prefetch_related(
            Prefetch(
                "versions",
                queryset=ValidationWorkflowVersion.objects.order_by(
                    "-version_major",
                    "-version_minor",
                    "-version_patch",
                    "-id",
                ),
            )
        )
        .distinct()
    )

    workflow_updates = []
    new_workflows = []

    version_to_workflow = {}

    for wf in workflows:
        versions = list(wf.versions.all())
        if not versions:
            continue

        latest = versions[0]

        workflow_updates.append(
            ValidationWorkflow(
                id=wf.id,
                created_by_id=latest.created_by_id,
                updated_by_id=latest.updated_by_id,
            )
        )

        version_to_workflow[latest.id] = wf.id

        for version in versions[1:]:
            new_workflows.append(
                (
                    version,
                    ValidationWorkflow(
                        account_id=wf.account_id,
                        name=f"{wf.name}-v{version.version}",
                        description=wf.description,
                        created_by_id=version.created_by_id,
                        updated_by_id=version.updated_by_id,
                    ),
                )
            )

    if workflow_updates:
        ValidationWorkflow.objects.bulk_update(
            workflow_updates,
            ["created_by", "updated_by"],
            batch_size=BATCH_SIZE,
        )

    created_workflows = ValidationWorkflow.objects.bulk_create(
        [wf for _, wf in new_workflows],
        batch_size=BATCH_SIZE,
    )

    for (version, _), created in zip(new_workflows, created_workflows):
        version_to_workflow[version.id] = created.id

    for version_id, workflow_id in version_to_workflow.items():
        ValidationNodeTemplate.objects.filter(new_workflow_id=version_id).update(workflow_id=workflow_id)

    # Force Postgres to flush and validate all triggers right now
    # so it won't block subsequent Django backward ALTER operations
    schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE;")


